<?php
ini_set('display_errors','0');
ini_set('display_startup_errors','0');
error_reporting(E_ALL);
if (session_status() === PHP_SESSION_NONE) session_start();
require_once __DIR__.'/includes/config.php';
require_once __DIR__.'/includes/database.php';
require_once __DIR__.'/includes/mailer.php';
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function rlog($m,$c=[]){$d=__DIR__.'/logs';if(!is_dir($d))@mkdir($d,0755,true);@error_log(date('Y-m-d H:i:s').' | '.$m.' | '.json_encode($c,JSON_UNESCAPED_UNICODE).PHP_EOL,3,$d.'/register_errors.log');@error_log($m.' | '.json_encode($c));}
function csrf(){if(empty($_SESSION['simple_reg_csrf']))$_SESSION['simple_reg_csrf']=bin2hex(random_bytes(32));return $_SESSION['simple_reg_csrf'];}
function csrf_ok($v){return !empty($v)&&!empty($_SESSION['simple_reg_csrf'])&&hash_equals($_SESSION['simple_reg_csrf'],$v);}
if(!isset($pdo)||!($pdo instanceof PDO))die('Database connection is not available. Check includes/database.php');
const OTP_LIFE=300; const OTP_TRIES=5;
$icons=['circle'=>'●','leaf'=>'🌿','heart'=>'♥','lotus'=>'🪷','star'=>'✦','moon'=>'☽','rose'=>'🌹','sun'=>'☀','cloud'=>'☁','flower'=>'🌸','spark'=>'✧','butterfly'=>'🦋','bird'=>'🐦','tree'=>'🌳','wave'=>'🌊','smile'=>'☺'];
$colors=['#5B8DEF','#6C63FF','#8B5CF6','#EC4899','#F43F5E','#F97316','#F59E0B','#10B981','#14B8A6','#06B6D4','#3B82F6','#84CC16'];
$f=['full_name'=>'','username'=>'','email'=>'','phone'=>'','password'=>'','confirm_password'=>'','anonymous_name'=>'','avatar_color'=>'#5B8DEF','avatar_icon'=>'circle','country'=>'','city'=>'','language'=>'en','birth_date'=>'','gender'=>'','occupation'=>'','education'=>'','reminder_time'=>'20:00'];
$errors=[];$success='';
$verified=!empty($_SESSION['simple_reg_verified']);$verifiedEmail=$_SESSION['simple_reg_verified_email']??'';$otpSent=!empty($_SESSION['simple_reg_otp_email']);
/* REALTIME AJAX */
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['ajax'])){
 $a=trim($_POST['ajax']);
 if(!csrf_ok($_POST['csrf']??'')) json_response(['ok'=>false,'message'=>'Security check failed.'],403);
 try{
  if($a==='username'){$v=trim($_POST['username']??'');if($v===''||!preg_match('/^[A-Za-z0-9_]{3,50}$/',$v))json_response(['ok'=>false,'message'=>'Use 3-50 letters, numbers or underscores.']);$q=$pdo->prepare('SELECT id FROM users WHERE LOWER(username)=LOWER(?) LIMIT 1');$q->execute([$v]);json_response(['ok'=>!$q->fetch(),'message'=>$q->fetch()?'Username is already taken.':'Username is available.']);}
  if($a==='email'){$v=strtolower(trim($_POST['email']??''));if(!filter_var($v,FILTER_VALIDATE_EMAIL))json_response(['ok'=>false,'message'=>'Enter a valid email.']);$q=$pdo->prepare('SELECT id FROM users WHERE LOWER(email)=LOWER(?) LIMIT 1');$q->execute([$v]);$exists=$q->fetch();json_response(['ok'=>!$exists,'message'=>$exists?'Email is already registered.':'Email is available.']);}
  if($a==='send_otp'){$v=strtolower(trim($_POST['email']??''));if(!filter_var($v,FILTER_VALIDATE_EMAIL))json_response(['ok'=>false,'message'=>'Enter a valid email.']);$q=$pdo->prepare('SELECT id FROM users WHERE LOWER(email)=LOWER(?) LIMIT 1');$q->execute([$v]);if($q->fetch())json_response(['ok'=>false,'message'=>'Email is already registered.']);$otp=(string)random_int(100000,999999);$sec=bin2hex(random_bytes(32));$_SESSION['simple_reg_otp_hash']=hash_hmac('sha256',$otp,$sec);$_SESSION['simple_reg_otp_secret']=$sec;$_SESSION['simple_reg_otp_email']=$v;$_SESSION['simple_reg_otp_expires']=time()+300;$_SESSION['simple_reg_otp_attempts']=0;try{$m=sendMail($v,'MindSphere — Email Verification',"Welcome to MindSphere.\n\nYour verification code is:\n\n$otp\n\nThis code expires in 5 minutes.",false);}catch(Throwable $e){rlog('OTP MAIL ERROR',['error'=>$e->getMessage()]);$m=['success'=>false];}if(empty($m['success']))jsonResponse(['ok'=>false,'message'=>'Could not send verification email.']);jsonResponse(['ok'=>true,'message'=>'Verification code sent.']);}
  if($a==='verify_otp'){$otp=preg_replace('/\D/','',$_POST['otp']??'');if(!preg_match('/^\d{6}$/',$otp))jsonResponse(['ok'=>false,'message'=>'Enter the 6-digit code.']);if(empty($_SESSION['simple_reg_otp_hash'])||empty($_SESSION['simple_reg_otp_secret'])||empty($_SESSION['simple_reg_otp_email'])||time()>(int)$_SESSION['simple_reg_otp_expires'])jsonResponse(['ok'=>false,'message'=>'Code expired or unavailable.']);$calc=hash_hmac('sha256',$otp,$_SESSION['simple_reg_otp_secret']);if(!hash_equals($_SESSION['simple_reg_otp_hash'],$calc))jsonResponse(['ok'=>false,'message'=>'Incorrect verification code.']);$em=strtolower($_SESSION['simple_reg_otp_email']);$_SESSION['simple_reg_verified']=true;$_SESSION['simple_reg_verified_email']=$em;unset($_SESSION['simple_reg_otp_hash'],$_SESSION['simple_reg_otp_secret'],$_SESSION['simple_reg_otp_email'],$_SESSION['simple_reg_otp_expires'],$_SESSION['simple_reg_otp_attempts']);jsonResponse(['ok'=>true,'email'=>$em,'message'=>'Email verified successfully.']);}
 }catch(Throwable $e){rlog('AJAX ERROR',['action'=>$a,'error'=>$e->getMessage()]);jsonResponse(['ok'=>false,'message'=>'Server error. Check register_errors.log.'],500);}
}

function json_response($data,$status=200){while(ob_get_level())ob_end_clean();http_response_code($status);header('Content-Type: application/json; charset=utf-8');echo json_encode($data,JSON_UNESCAPED_UNICODE);exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $a=$_POST['action']??'';
 if($a==='send_otp'){
  $email=strtolower(trim($_POST['email']??''));
  if(!csrf_ok($_POST['csrf']??''))$errors[]='Security check failed. Refresh and try again.';
  elseif(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email address.';
  else try{
   $q=$pdo->prepare('SELECT id FROM users WHERE LOWER(email)=LOWER(?) LIMIT 1');$q->execute([$email]);
   if($q->fetch())$errors[]='This email is already registered.';
   else{
    $otp=(string)random_int(100000,999999);$secret=bin2hex(random_bytes(32));
    $_SESSION['simple_reg_otp_hash']=hash_hmac('sha256',$otp,$secret);$_SESSION['simple_reg_otp_secret']=$secret;$_SESSION['simple_reg_otp_email']=$email;$_SESSION['simple_reg_otp_expires']=time()+OTP_LIFE;$_SESSION['simple_reg_otp_attempts']=0;
    try{$mail=sendMail($email,'MindSphere — Email Verification',"Welcome to MindSphere.\n\nYour verification code is:\n\n$otp\n\nThis code expires in 5 minutes.\n\nIf you did not request this code, ignore this email.",false);}catch(Throwable $e){$mail=['success'=>false];rlog('MAIL EXCEPTION',['error'=>$e->getMessage()]);}
    if(empty($mail['success'])){unset($_SESSION['simple_reg_otp_hash'],$_SESSION['simple_reg_otp_secret'],$_SESSION['simple_reg_otp_email'],$_SESSION['simple_reg_otp_expires'],$_SESSION['simple_reg_otp_attempts']);$errors[]='Could not send verification email.';}else{$otpSent=true;$success='Verification code sent.';}
   }
  }catch(Throwable $e){rlog('OTP DB ERROR',['error'=>$e->getMessage()]);$errors[]='Could not check this email.';}
  $f['email']=$email;
 }
 elseif($a==='verify_otp'){
  $otp=trim($_POST['otp']??'');
  if(!csrf_ok($_POST['csrf']??''))$errors[]='Security check failed. Refresh and try again.';
  elseif(!preg_match('/^\d{6}$/',$otp))$errors[]='Enter the 6-digit code.';
  elseif(empty($_SESSION['simple_reg_otp_hash'])||empty($_SESSION['simple_reg_otp_secret'])||empty($_SESSION['simple_reg_otp_email'])||empty($_SESSION['simple_reg_otp_expires']))$errors[]='No active code. Request a new code.';
  else{
   $_SESSION['simple_reg_otp_attempts']=(int)($_SESSION['simple_reg_otp_attempts']??0)+1;
   if($_SESSION['simple_reg_otp_attempts']>OTP_TRIES){$errors[]='Too many attempts. Request a new code.';unset($_SESSION['simple_reg_otp_hash'],$_SESSION['simple_reg_otp_secret'],$_SESSION['simple_reg_otp_email'],$_SESSION['simple_reg_otp_expires'],$_SESSION['simple_reg_otp_attempts']);}
   elseif(time()>(int)$_SESSION['simple_reg_otp_expires']){$errors[]='Code expired. Request a new code.';unset($_SESSION['simple_reg_otp_hash'],$_SESSION['simple_reg_otp_secret'],$_SESSION['simple_reg_otp_email'],$_SESSION['simple_reg_otp_expires'],$_SESSION['simple_reg_otp_attempts']);}
   elseif(!hash_equals($_SESSION['simple_reg_otp_hash'],hash_hmac('sha256',$otp,$_SESSION['simple_reg_otp_secret'])))$errors[]='Incorrect verification code.';
   else{$verified=true;$verifiedEmail=strtolower($_SESSION['simple_reg_otp_email']);$_SESSION['simple_reg_verified']=true;$_SESSION['simple_reg_verified_email']=$verifiedEmail;unset($_SESSION['simple_reg_otp_hash'],$_SESSION['simple_reg_otp_secret'],$_SESSION['simple_reg_otp_email'],$_SESSION['simple_reg_otp_expires'],$_SESSION['simple_reg_otp_attempts']);$otpSent=false;$success='Email verified successfully.';}
  }
 }
 elseif($a==='create_account'){
  foreach(array_keys($f) as $k)$f[$k]=trim((string)($_POST[$k]??$f[$k]));
  $f['email']=strtolower($f['email']);
  if(!csrf_ok($_POST['csrf']??''))$errors[]='Security check failed. Refresh and try again.';
  if(!$verified||empty($verifiedEmail))$errors[]='Please verify your email first.';
  elseif($f['email']!==strtolower($verifiedEmail))$errors[]='The verified email does not match.';
  if(strlen($f['username'])<3||strlen($f['username'])>50)$errors[]='Username must be 3–50 characters.';
  if(!preg_match('/^[A-Za-z0-9_]+$/',$f['username']))$errors[]='Username may contain only letters, numbers and underscores.';
  if(!filter_var($f['email'],FILTER_VALIDATE_EMAIL))$errors[]='Invalid email address.';
  if(strlen($f['password'])!==8)$errors[]='Password must be exactly 8 characters.';
  if(!preg_match('/[A-Z]/',$f['password']))$errors[]='Password needs an uppercase letter.';
  if(!preg_match('/[a-z]/',$f['password']))$errors[]='Password needs a lowercase letter.';
  if(!preg_match('/[0-9]/',$f['password']))$errors[]='Password needs a number.';
  if($f['password']!==$f['confirm_password'])$errors[]='Passwords do not match.';
  if($f['anonymous_name']==='')$f['anonymous_name']='New Member';
  if(strlen($f['anonymous_name'])>50)$errors[]='Anonymous name is too long.';
  if(!isset($icons[$f['avatar_icon']]))$f['avatar_icon']='circle';
  if(!in_array($f['avatar_color'],$colors,true))$f['avatar_color']='#5B8DEF';
  if(empty($errors))try{
   $q=$pdo->prepare('SELECT id FROM users WHERE LOWER(username)=LOWER(?) OR LOWER(email)=LOWER(?) LIMIT 1');$q->execute([$f['username'],$f['email']]);if($q->fetch())$errors[]='Username or email is already registered.';
  }catch(Throwable $e){rlog('CHECK ERROR',['error'=>$e->getMessage()]);$errors[]='Could not check account availability.';}
  if(empty($errors))try{
   $hash=password_hash($f['password'],PASSWORD_DEFAULT);if(!$hash)throw new RuntimeException('Password hashing failed.');
   $sql="INSERT INTO users (full_name,email,phone,username,password_hash,role,anonymous_name,bio,country,city,language,birth_date,gender,is_active,created_at,last_login,occupation,education,avatar_color,avatar_icon,reminder_time,email_verified) VALUES (?,?,?,?,?,'user',?, '',?,?,?,?,?,1,NOW(),NOW(),?,?,?,?,?,1)";
   $q=$pdo->prepare($sql);$q->execute([$f['full_name']!==''?$f['full_name']:null,$f['email'],$f['phone']!==''?$f['phone']:null,$f['username'],$hash,$f['anonymous_name'],$f['country']!==''?$f['country']:null,$f['city']!==''?$f['city']:null,$f['language']?:'en',$f['birth_date']!==''?$f['birth_date']:null,$f['gender']!==''?$f['gender']:null,$f['occupation']!==''?$f['occupation']:null,$f['education']!==''?$f['education']:null,$f['avatar_color'],$f['avatar_icon'],$f['reminder_time']?:'20:00']);
   $id=(int)$pdo->lastInsertId();if($id<=0)throw new RuntimeException('No user ID returned after insert.');
   $q=$pdo->prepare('INSERT INTO profiles (user_id,anonymous_name,avatar_color) VALUES (?,?,?)');$q->execute([$id,$f['anonymous_name'],$f['avatar_color']]);
   session_regenerate_id(true);$_SESSION['user_id']=$id;$_SESSION['role']='user';$_SESSION['username']=$f['username'];$_SESSION['email']=$f['email'];$_SESSION['anonymous_name']=$f['anonymous_name'];$_SESSION['avatar_color']=$f['avatar_color'];$_SESSION['avatar_icon']=$f['avatar_icon'];
   unset($_SESSION['simple_reg_verified'],$_SESSION['simple_reg_verified_email'],$_SESSION['simple_reg_otp_hash'],$_SESSION['simple_reg_otp_secret'],$_SESSION['simple_reg_otp_email'],$_SESSION['simple_reg_otp_expires'],$_SESSION['simple_reg_otp_attempts']);
   header('Location: dashboard.php');exit;
  }catch(Throwable $e){rlog('ACCOUNT CREATION FAILED',['error'=>$e->getMessage(),'code'=>$e->getCode(),'email'=>$f['email'],'username'=>$f['username']]);$errors[]='ACCOUNT CREATION FAILED: '.$e->getMessage();}
 }
}
$verified=!empty($_SESSION['simple_reg_verified']);$verifiedEmail=$_SESSION['simple_reg_verified_email']??'';$otpSent=!empty($_SESSION['simple_reg_otp_email']);
if($f['anonymous_name']===''){$f['anonymous_name']='Blue Sparrow';}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MindSphere Register</title><style>
:root{--bg:#e8ecf3;--text:#253047;--muted:#788399;--p:#667eea;--p2:#8b5cf6;--ok:#19a463;--bad:#df5260;--s:#e8ecf3;--dark:#c5cad4;--light:#fff}*{box-sizing:border-box}body{font-family:Inter,system-ui,sans-serif;background:var(--bg);color:var(--text);margin:0;min-height:100vh;transition:.3s}.box{width:min(980px,calc(100% - 24px));margin:35px auto;padding:30px;background:var(--s);border-radius:30px;box-shadow:18px 18px 40px var(--dark),-18px -18px 40px var(--light);position:relative;overflow:hidden}.box:before{content:'';position:absolute;width:240px;height:240px;border-radius:50%;right:-90px;top:-100px;background:linear-gradient(135deg,#667eea33,#8b5cf633);filter:blur(5px)}h1{text-align:center;font-size:32px;margin:0 0 8px}.box>p{text-align:center;color:var(--muted);margin:0 0 25px}.field{margin:14px 0}label{display:block;font-weight:750;margin-bottom:7px;font-size:13px}.row{display:grid;grid-template-columns:1fr 1fr;gap:14px}input,select{width:100%;padding:13px 15px;border:0;border-radius:15px;background:var(--s);color:var(--text);outline:0;box-shadow:inset 4px 4px 9px var(--dark),inset -4px -4px 9px var(--light);transition:.2s}input:focus,select:focus{box-shadow:inset 2px 2px 5px var(--dark),inset -2px -2px 5px var(--light),0 0 0 3px #667eea22}input.valid{box-shadow:inset 4px 4px 9px var(--dark),inset -4px -4px 9px var(--light),0 0 0 2px #19a46366}input.invalid{box-shadow:inset 4px 4px 9px var(--dark),inset -4px -4px 9px var(--light),0 0 0 2px #df526066}button{padding:12px 17px;border:0;border-radius:14px;background:linear-gradient(135deg,var(--p),var(--p2));color:#fff;font-weight:800;cursor:pointer;box-shadow:7px 7px 15px var(--dark),-5px -5px 12px var(--light);transition:.2s}button:hover{transform:translateY(-2px)}button:disabled{opacity:.45;cursor:not-allowed;transform:none}.alert{padding:14px 16px;border-radius:15px;margin:13px 0;box-shadow:inset 3px 3px 8px var(--dark),inset -3px -3px 8px var(--light)}.err{color:var(--bad)}.ok{color:var(--ok)}.verify{padding:20px;border-radius:22px;box-shadow:inset 5px 5px 12px var(--dark),inset -5px -5px 12px var(--light);margin-bottom:22px}.hint,.live{font-size:12px;color:var(--muted);margin-top:6px}.live.ok{color:var(--ok)}.live.bad{color:var(--bad)}.icons{display:flex;flex-wrap:wrap;gap:8px}.icon{width:44px;height:44px;padding:0;background:var(--s);color:var(--text)}.icon.sel{box-shadow:inset 3px 3px 7px var(--dark),inset -3px -3px 7px var(--light);color:var(--p)}.colors{display:flex;gap:10px;flex-wrap:wrap;margin-top:12px}.color{width:30px;height:30px;padding:0;border-radius:50%;border:3px solid var(--s);outline:1px solid #aeb6c5}.color.sel{outline:3px solid var(--text)}.rose{font-size:76px;text-align:center;display:block;margin:5px auto 15px;filter:drop-shadow(8px 10px 10px #0002)}.strength{height:5px;border-radius:10px;margin-top:8px;box-shadow:inset 2px 2px 5px var(--dark),inset -2px -2px 5px var(--light);overflow:hidden}.strength i{display:block;height:100%;width:0;background:linear-gradient(90deg,#ef4444,#f59e0b,#22c55e);transition:.25s}.rules{display:grid;grid-template-columns:1fr 1fr;margin-top:7px;gap:4px}.rule{font-size:11px;color:var(--muted)}.rule.pass{color:var(--ok)}.rule.pass:before{content:'✓ ';}.otp-row{display:grid;grid-template-columns:1fr auto;gap:10px}.otp-area{margin-top:14px;display:none}.otp-area.show{display:block}.otp{font-size:23px;text-align:center;font-weight:800}.verified{color:var(--ok);font-weight:800;padding:13px;border-radius:15px;box-shadow:inset 3px 3px 8px var(--dark),inset -3px -3px 8px var(--light)}.avatar-preview{width:85px;height:85px;border-radius:28px;display:grid;place-items:center;font-size:40px;color:#fff;margin:10px auto 14px;box-shadow:10px 10px 20px var(--dark),-10px -10px 20px var(--light)}@media(max-width:650px){.row{grid-template-columns:1fr}.box{padding:20px;margin:12px auto}.otp-row{grid-template-columns:1fr}}
body.dark{--bg:#171a22;--s:#171a22;--text:#eef2f8;--muted:#9aa4b5;--dark:#0d0f14;--light:#252a35}
</style>></head><body><div class="box"><h1>🌹 MindSphere Registration</h1><p>Simple one-step account registration.</p>
<?php if($errors):?><div class="alert err"><?php foreach($errors as $e):?><div><?=h($e)?></div><?php endforeach;?></div><?php endif;?><?php if($success):?><div class="alert ok"><?=h($success)?></div><?php endif;?>
<div class="verify"><h3>Email verification</h3><?php if($verified):?><div class="alert ok">✓ Verified: <strong><?=h($verifiedEmail)?></strong></div><?php else:?><form method="post"><input type="hidden" name="action" value="send_otp"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="row"><input type="email" name="email" placeholder="you@example.com" value="<?=h($f['email'])?>" required><button>Send code</button></div></form><?php if($otpSent):?><form method="post" style="margin-top:12px"><input type="hidden" name="action" value="verify_otp"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="row"><input type="text" name="otp" maxlength="6" inputmode="numeric" pattern="[0-9]{6}" placeholder="6-digit code" required><button>Verify</button></div><div class="hint">Code expires in 5 minutes.</div></form><?php endif;?><?php endif;?></div>
<form method="post" autocomplete="off"><input type="hidden" name="action" value="create_account"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><h3>Create account</h3>
<div class="row"><div class="field"><label>Full name</label><input name="full_name" maxlength="100" value="<?=h($f['full_name'])?>"></div><div class="field"><label>Username *</label><input name="username" minlength="3" maxlength="50" pattern="[A-Za-z0-9_]+" value="<?=h($f['username'])?>" required></div></div>
<div class="field"><label>Verified email *</label><input type="email" name="email" value="<?=h($verified?$verifiedEmail:$f['email'])?>" <?=($verified?'readonly':'')?> required></div>
<div class="field"><label>Phone</label><input name="phone" maxlength="20" value="<?=h($f['phone'])?>"></div>
<div class="row"><div class="field"><label>Password * (exactly 8 chars)</label><input id="p" type="password" name="password" maxlength="8" minlength="8" required><div class="hint">Uppercase + lowercase + number.</div></div><div class="field"><label>Confirm password *</label><input id="cp" type="password" name="confirm_password" maxlength="8" minlength="8" required></div></div>
<div class="field"><label>Anonymous name *</label><input name="anonymous_name" maxlength="50" value="<?=h($f['anonymous_name'])?>" required></div>
<div class="field"><label>Avatar icon</label><input type="hidden" id="ai" name="avatar_icon" value="<?=h($f['avatar_icon'])?>"><div class="icons"><?php foreach($icons as $k=>$v):?><button type="button" class="icon <?=($f['avatar_icon']===$k?'sel':'')?>" data-v="<?=h($k)?>"><?=h($v)?></button><?php endforeach;?></div></div>
<div class="field"><label>Avatar color</label><input type="hidden" id="ac" name="avatar_color" value="<?=h($f['avatar_color'])?>"><div class="colors"><?php foreach($colors as $c):?><button type="button" class="color <?=($f['avatar_color']===$c?'sel':'')?>" style="background:<?=h($c)?>" data-v="<?=h($c)?>"></button><?php endforeach;?></div></div>
<div class="row"><div class="field"><label>Country</label><input name="country" maxlength="50" value="<?=h($f['country'])?>"></div><div class="field"><label>City</label><input name="city" maxlength="100" value="<?=h($f['city'])?>"></div></div>
<div class="row"><div class="field"><label>Language</label><select name="language"><option value="en">English</option><option value="bn" <?=($f['language']==='bn'?'selected':'')?>>বাংলা</option><option value="ar" <?=($f['language']==='ar'?'selected':'')?>>العربية</option></select></div><div class="field"><label>Reminder time</label><input type="time" name="reminder_time" value="<?=h($f['reminder_time'])?>"></div></div>
<div class="row"><div class="field"><label>Birth date</label><input type="date" name="birth_date" value="<?=h($f['birth_date'])?>"></div><div class="field"><label>Gender</label><select name="gender"><option value="">Prefer not to say</option><option value="male">Male</option><option value="female">Female</option><option value="other">Other</option></select></div></div>
<div class="row"><div class="field"><label>Occupation</label><input name="occupation" maxlength="100" value="<?=h($f['occupation'])?>"></div><div class="field"><label>Education</label><input name="education" maxlength="50" value="<?=h($f['education'])?>"></div></div>
<button type="submit" style="width:100%" <?=(!$verified?'disabled':'')?>>Create Account</button><?php if(!$verified):?><div class="hint" style="text-align:center;margin-top:8px">Verify the email above first.</div><?php endif;?></form></div><script src="https://cdn.jsdelivr.net/npm/gsap@3.13.0/dist/gsap.min.js"></script><script>
const CSRF=<?=json_encode(csrf())?>, ICONS=<?=json_encode($icons,JSON_UNESCAPED_UNICODE)?>;const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s);function live(e,m,c=''){if(e){e.textContent=m;e.className='live '+c}}function state(e,v){e.classList.remove('valid','invalid');if(v)e.classList.add(v)}function db(fn,ms){let t;return(...a)=>{clearTimeout(t);t=setTimeout(()=>fn(...a),ms)}}async function api(x){x.csrf=CSRF;const r=await fetch(location.href,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams(x)});const j=await r.json();return j}
if(window.gsap){gsap.from('.box',{opacity:0,y:30,duration:.8,ease:'power3.out'});gsap.from('.rose',{scale:.4,rotation:-15,opacity:0,duration:1,ease:'elastic.out(1,.5)'});gsap.to('.rose',{y:-8,rotation:4,duration:2,yoyo:true,repeat:-1,ease:'sine.inOut'})}
// dark/light
const theme=document.createElement('button');theme.textContent='☾';theme.style.cssText='position:absolute;right:20px;top:20px;border-radius:50%;width:42px;height:42px;padding:0';document.querySelector('.box').prepend(theme);if(localStorage.msTheme==='dark')document.body.classList.add('dark');theme.onclick=()=>{document.body.classList.toggle('dark');localStorage.msTheme=document.body.classList.contains('dark')?'dark':'light';theme.textContent=document.body.classList.contains('dark')?'☀':'☾'};
// username realtime
$('#username')?.addEventListener('input',db(async e=>{const v=e.target.value.trim();if(!v){live(document.querySelector('#username')?.parentElement.querySelector('.live'),'');return}const q=document.createElement('span');q.className='live';q.textContent='Checking…';if(!e.target.parentElement.querySelector('.live'))e.target.parentElement.appendChild(q);const j=await api({ajax:'username',username:v});const el=e.target.parentElement.querySelector('.live');live(el,j.message,j.ok?'ok':'bad');state(e.target,j.ok?'valid':'invalid')},350));
// email realtime
const emailInput=document.querySelector('input[name="email"]');emailInput?.addEventListener('input',db(async e=>{if(e.target.readOnly)return;const j=await api({ajax:'email',email:e.target.value.trim()});let el=e.target.parentElement.querySelector('.live');if(!el){el=document.createElement('div');e.target.parentElement.appendChild(el)}live(el,j.message,j.ok?'ok':'bad');state(e.target,j.ok?'valid':'invalid')},450));
// OTP realtime
const verifyBox=document.querySelector('.verify');const sendBtn=verifyBox?.querySelector('button');const verifyInput=verifyBox?.querySelector('input[type="email"]');if(sendBtn&&verifyInput){sendBtn.addEventListener('click',async()=>{const j=await api({ajax:'send_otp',email:verifyInput.value.trim()});let el=verifyBox.querySelector('.live');if(!el){el=document.createElement('div');verifyBox.appendChild(el)}live(el,j.message,j.ok?'ok':'bad');if(j.ok){let area=verifyBox.querySelector('.otp-area');if(!area){area=document.createElement('div');area.className='otp-area show';area.innerHTML='<div class="otp-row"><input class="otp" id="liveOtp" maxlength="6" inputmode="numeric" placeholder="6-digit code"><button type="button" id="liveVerify">Verify</button></div><div class="live" id="otpMsg"></div>';verifyBox.appendChild(area);$('#liveVerify').onclick=verifyLiveOtp;$('#liveOtp').addEventListener('input',e=>{e.target.value=e.target.value.replace(/\D/g,'').slice(0,6);if(e.target.value.length===6)verifyLiveOtp()})}area.classList.add('show');$('#liveOtp')?.focus()}})}async function verifyLiveOtp(){const j=await api({ajax:'verify_otp',otp:$('#liveOtp').value});live($('#otpMsg'),j.message,j.ok?'ok':'bad');if(j.ok){verifyBox.innerHTML='<div class="verified">✓ Email verified: '+j.email+'</div>';const ae=document.querySelector('form[action=""] input[name="email"]')||document.querySelector('form:not(.verify) input[name="email"]');document.querySelectorAll('input[name="email"]').forEach(x=>{x.value=j.email;x.readOnly=true});const submit=document.querySelector('form:not(.verify) button[type="submit"]');if(submit)submit.disabled=false;if(window.gsap)gsap.from('.verified',{scale:.8,opacity:0,duration:.5,ease:'back.out(2)'})}}
// password realtime
const pw=document.querySelector('#p'),cp=document.querySelector('#cp');if(pw){const wrap=pw.parentElement;const bar=document.createElement('div');bar.className='strength';bar.innerHTML='<i></i>';pw.after(bar);const rules=document.createElement('div');rules.className='rules';rules.innerHTML='<span class="rule" data-r="len">8 characters</span><span class="rule" data-r="up">Uppercase</span><span class="rule" data-r="lo">Lowercase</span><span class="rule" data-r="num">Number</span>';bar.after(rules);function check(){const p=pw.value,rs={len:p.length===8,up:/[A-Z]/.test(p),lo:/[a-z]/.test(p),num:/[0-9]/.test(p)};Object.keys(rs).forEach(k=>rules.querySelector('[data-r='+k+']').classList.toggle('pass',rs[k]));bar.firstElementChild.style.width=(Object.values(rs).filter(Boolean).length*25)+'%';if(cp&&cp.value){const ok=cp.value===p;state(cp,ok?'valid':'invalid')}}pw.addEventListener('input',check);cp?.addEventListener('input',check)}
// avatar live preview
const ai=document.querySelector('#ai'),ac=document.querySelector('#ac');if(ai&&ac){const prev=document.createElement('div');prev.className='avatar-preview';prev.textContent=ICONS[ai.value]||'●';prev.style.background=ac.value;ai.parentElement.before(prev);$$('.icon').forEach(b=>b.addEventListener('click',()=>{ai.value=b.dataset.v;prev.textContent=ICONS[ai.value];if(window.gsap)gsap.from(prev,{scale:.7,rotation:-15,duration:.35,ease:'back.out(2)'})}));$$('.color').forEach(b=>b.addEventListener('click',()=>{ac.value=b.dataset.v;prev.style.background=ac.value}))}
</script></body></html>
